587	    <span class="count-badge">${all.length} 个英雄</span>
588	    <span class="hint">⚠️ 不同分路英雄职责不同，建议以分路内排名为主</span></div>`;
589	  html += renderTable(all, gameConfig.globalColumns, null);
590	  return html;
591	}
592	
593	function renderAll() {
594	  if (!gameData) return;
595	  const content = document.getElementById("content");
596	
597	  // 网格视图 — 单独处理
598	  if (currentViewMode === "grid") {
599	    let heroes;
600	    if (!gameData.hasLanes) {
601	      heroes = gameData.heroes;
602	    } else if (currentView === "global") {
603	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
604	    } else {
605	      heroes = gameData.lanes[currentLane] || [];
606	    }
607	
608	    let titleHtml;
609	    if (!gameData.hasLanes) {
610	      titleHtml = `<div class="section-header">
611	        <h2>${gameConfig.gameIcon} ${gameConfig.gameName} 梯度排行</h2>
612	        <span class="count-badge">${heroes.length} 个英雄</span></div>`;
613	    } else if (currentView === "global") {
614	      titleHtml = `<div class="section-header">
615	        <h2>🌍 全局排名（跨分路对比）</h2>
616	        <span class="count-badge">${heroes.length} 个英雄</span>
617	        <span class="hint">⚠️ 不同分路英雄职责不同，建议以分路内排名为主</span></div>`;
618	    } else {
619	      titleHtml = `<div class="section-header">
620	        <h2>${currentLane}</h2>
621	        <span class="count-badge">${heroes.length} 个英雄</span></div>`;
622	    }
623	    content.innerHTML = titleHtml + renderGridView(heroes, null);
624	    return;
625	  }
626	
627	  // 表格视图
628	  if (!gameData.hasLanes) {
629	    content.innerHTML = renderLaneView();
630	    return;
631	  }
632	
633	  if (currentView === "global") {
634	    content.innerHTML = renderGlobalView();
635	  } else {
636	    content.innerHTML = renderLaneView(currentLane);
637	  }
638	}
639	
640	// ============================================================
641	// 搜索
642	// ============================================================
643	function doSearch(query) {
644	  if (!query || query.trim().length === 0) {
645	    renderAll();
646	    return;
647	  }
648	  const q = query.trim().toLowerCase();
649	  let results = [];
650	
651	  if (gameData.hasLanes) {
652	    for (const heroes of Object.values(gameData.lanes)) {
653	      for (const h of heroes) {
654	        if (h.name.toLowerCase().includes(q)) results.push(h);
655	      }
656	    }
657	  } else {
658	    results = gameData.heroes.filter(h => h.name.toLowerCase().includes(q));
659	  }
660	
661	  if (results.length === 0) {
662	    document.getElementById("content").innerHTML =
663	      `<p style="text-align:center;padding:40px;color:#8b949e;">未找到匹配 "${query}" 的英雄</p>`;
664	    return;
665	  }
666	
667	  // Sort by score descending
668	  const scoreKey = getScoreField();
669	  const rankKey = gameData.hasLanes ? (currentMethod === "zscore" ? "_rank_zscore" : "_rank_simple") : "rank";
670	  results.sort((a, b) => b[scoreKey] - a[scoreKey]);
671	  // Set laneRank for display
672	  results.forEach(h => { h.laneRank = h[rankKey] || 0; });
673	
674	  // Search result columns
675	  let searchCols;
676	  if (gameData.hasLanes) {
677	    searchCols = [
678	      { label: "分路排名", field: "laneRank", type: "rank" },
679	      { label: "英雄", field: "name", type: "text" },
680	      { label: "分路", field: "lane", type: "text" },
681	      { label: "梯度", field: "tier", type: "tier" },
682	      { label: "评分", field: "score", type: "score" },
683	      { label: "胜率", field: "wr", type: "pct", colorClass: "wr" },
684	      { label: "出场率", field: "pr", type: "pct" },
685	      { label: "Ban率", field: "br", type: "pct" },
686	      { label: "BP率", field: "bp", type: "pct" },
687	      { label: "全局排名", field: "globalRank", type: "rank" }
688	    ];
689	  } else {
690	    searchCols = gameConfig.columns;
691	  }
692	
693	  let html = `<div class="section-header">
694	    <h2>🔍 搜索结果："${query}"</h2>
695	    <span class="count-badge">${results.length} 个英雄</span></div>`;
696	  html += renderTable(results, searchCols, null);
697	  document.getElementById("content").innerHTML = html;
698	}
