767	    const txt = b.textContent;
768	    if (txt.includes("Z-score") || txt.includes("简易公式") || txt.includes("加权和")) {
769	      const isZ = txt.includes("Z-score");
770	      const isS = txt.includes("简易公式");
771	      const isW = txt.includes("加权和");
772	      b.className = (isZ && method === "zscore") || (isS && method === "simple") || (isW && method === "weighted") ? "active" : "";
773	    }
