811	      <button onclick="switchMethod('simple')">简易公式</button>`;
812	  } else if (!gameConfig.hasLanes) {
813	    html += `<span class="label">算法：</span>
814	      <button class="active" onclick="switchMethod('weighted')">加权和 (0.20/0.50/0.30)</button>`;
815	  }
816	
817	  if (gameConfig.hasLanes) {
818	    html += `<span style="margin-left:16px" class="label">视图：</span>
819	      <button id="btn-lane" class="active" onclick="switchView('lane')">📋 分路排名</button>
820	      <button id="btn-global" onclick="switchView('global')">🌍 全局排名</button>`;
821	  }
822	
823	  // 展示模式切换
824	  html += `<span style="margin-left:16px" class="label">展示：</span>
825	    <button id="btn-table" class="active" onclick="switchViewMode('table')">📋 表格</button>
826	    <button id="btn-grid" onclick="switchViewMode('grid')">🎨 网格</button>`;
827	
