861	  document.querySelectorAll(".game-selector button").forEach(b => {
862	    b.className = b.dataset.game === gameId ? "active" : "";
863	  });
864	
865	  // Load config
866	  const base = gameId === "lolm" ? "lolm" : "曙光英雄";
867	  const configResp = await fetch(base + "/config.json");
868	  if (!configResp.ok) throw new Error(`加载 ${gameId} 配置失败: ${configResp.status}`);
869	  gameConfig = await configResp.json();
870	
871	  // Reset state
872	  currentMethod = gameConfig.algorithm.type === "weighted" ? "weighted" : "zscore";
873	  currentView = "lane";
874	  currentLane = gameConfig.hasLanes ? gameConfig.lanes[0].name : null;
875	
876	  // Clear search box
877	  const searchBox = document.querySelector(".search-box");
878	  if (searchBox) searchBox.value = "";
879	
880	  // Load data
881	  document.getElementById("content").innerHTML =
882	    '<p style="text-align:center;padding:60px;color:#8b949e;">⏳ 加载中...</p>';
883	
884	  await loadGameData();
885	
886	  // Rebuild UI
887	  buildControls();
888	  buildNav();
